import json
C={}
def add(sid,name,latin,group,summary,**kw):
    d={'name':name,'latin':latin,'group':group,'summary':summary}; d.update(kw); C[sid]=d
# ---------- bones ----------
b=lambda s,*a,**k: add('bone.'+s,*a,**k)
b('frontal_bone','Frontal bone','Os frontale','Cranium','Forms the forehead, the roofs of the orbits and most of the anterior cranial fossa. Contains the frontal sinuses.')
b('parietal_bone','Parietal bone','Os parietale','Cranium','Paired bones forming the sides and roof of the cranial vault; they meet in the midline at the sagittal suture.')
b('occipital_bone','Occipital bone','Os occipitale','Cranium','Forms the back and much of the base of the skull. Surrounds the foramen magnum; its occipital condyles articulate with the atlas (C1).')
b('temporal_bone','Temporal bone','Os temporale','Cranium','Houses the middle and inner ear. Bears the mandibular fossa of the temporomandibular joint, and the mastoid, styloid and zygomatic processes.')
b('sphenoid_bone','Sphenoid bone','Os sphenoidale','Cranium','Central bone of the skull base. Its sella turcica holds the pituitary gland; its wings and pterygoid processes give passage and attachment to many nerves and muscles.')
b('ethmoid_bone','Ethmoid bone','Os ethmoidale','Cranium','Light, air-filled bone between the orbits. Its cribriform plate transmits olfactory nerve fibres; it forms part of the nasal septum and the superior and middle nasal conchae.')
b('maxilla','Maxilla','Maxilla','Facial skeleton','The upper jaw. Holds the upper teeth and forms the floor of the orbit, part of the hard palate and the lateral wall of the nasal cavity. Contains the maxillary sinus.')
b('zygomatic_bone','Zygomatic bone','Os zygomaticum','Facial skeleton','The cheekbone. Forms the prominence of the cheek and part of the lateral orbital wall; with the temporal bone it forms the zygomatic arch.')
b('nasal_bone','Nasal bone','Os nasale','Facial skeleton','Small paired bones forming the bony bridge of the nose.')
b('lacrimal_bone','Lacrimal bone','Os lacrimale','Facial skeleton','The smallest facial bone, in the medial wall of the orbit. Helps form the fossa for the lacrimal sac.')
b('palatine_bone','Palatine bone','Os palatinum','Facial skeleton','L-shaped bone forming the posterior hard palate and parts of the nasal cavity wall and orbital floor.')
b('inferior_nasal_concha','Inferior nasal concha','Concha nasalis inferior','Facial skeleton','A separate scroll-shaped bone on the lateral wall of the nasal cavity. The nasolacrimal duct opens beneath it, into the inferior meatus.')
b('vomer','Vomer','Vomer','Facial skeleton','Thin midline bone forming the posteroinferior part of the nasal septum.')
b('mandible','Mandible','Mandibula','Facial skeleton','The lower jaw, the only movable bone of the skull. Holds the lower teeth; its condyles form the temporomandibular joints. The mental foramen transmits the mental nerve and vessels.')
b('hyoid_bone','Hyoid bone','Os hyoideum','Neck','U-shaped bone that does not articulate with any other bone. Suspended by muscles and ligaments, it anchors the tongue and the supra- and infrahyoid muscles.')
b('atlas_c1','Atlas (C1)','Atlas','Cervical spine','First cervical vertebra. Has no body; it carries the skull, and the atlanto-occipital joints allow nodding.')
b('axis_c2','Axis (C2)','Axis','Cervical spine','Second cervical vertebra. Its dens (odontoid process) is the pivot around which the atlas and skull rotate.')
b('major_alar_cartilage','Major alar cartilage','Cartilago alaris major','Nasal cartilage','Shapes the tip of the nose and the margins of the nostrils.')
b('lateral_nasal_cartilage','Lateral process of septal cartilage','Processus lateralis cartilaginis septi nasi','Nasal cartilage','Also called the upper lateral cartilage. Supports the middle third of the external nose, below the nasal bones.')
b('septal_cartilage','Septal nasal cartilage','Cartilago septi nasi','Nasal cartilage','Forms the anterior, cartilaginous part of the nasal septum.')
b('maxillary_teeth','Upper (maxillary) teeth','Arcus dentalis maxillaris','Teeth','Incisors, canines, premolars and first and second molars of the upper jaw (third molars are not modelled). Sensory supply from the superior alveolar nerves (maxillary nerve, V2).')
b('mandibular_teeth','Lower (mandibular) teeth','Arcus dentalis mandibularis','Teeth','Incisors, canines, premolars and first and second molars of the lower jaw (third molars are not modelled). Sensory supply from the inferior alveolar nerve (V3).')
# ---------- muscles ----------
def m(s,name,latin,group,summary,o,i,n,a): add('muscle.'+s,name,latin,group,summary,origin=o,insertion=i,innervation=n,action=a)
FE='Facial expression'
m('frontalis','Frontalis (frontal belly of occipitofrontalis)','Venter frontalis musculi occipitofrontalis',FE,'Broad muscle of the forehead.','Epicranial aponeurosis','Skin of the eyebrows and forehead','Temporal branches of the facial nerve (CN VII)','Raises the eyebrows and wrinkles the forehead')
m('occipitalis','Occipitalis (occipital belly of occipitofrontalis)','Venter occipitalis musculi occipitofrontalis',FE,'Posterior belly of the scalp muscle.','Lateral superior nuchal line and mastoid part of the temporal bone','Epicranial aponeurosis','Posterior auricular branch of the facial nerve (CN VII)','Draws the scalp backwards')
m('temporoparietalis','Temporoparietalis','Musculus temporoparietalis',FE,'Thin, variable muscle sheet of the scalp above the ear.','Fascia above the auricle','Epicranial aponeurosis','Temporal branches of the facial nerve (CN VII)','Tightens the scalp')
add('muscle.epicranial_aponeurosis','Epicranial aponeurosis','Galea aponeurotica',FE,'Tough fibrous sheet covering the vault of the skull. It links the frontal and occipital bellies of occipitofrontalis and is one of the layers of the scalp.')
m('procerus','Procerus','Musculus procerus',FE,'Small muscle over the bridge of the nose.','Fascia over the nasal bone and upper lateral nasal cartilage','Skin between the eyebrows','Facial nerve (CN VII)','Pulls the medial eyebrows down, making horizontal wrinkles over the bridge of the nose')
m('corrugator_supercilii','Corrugator supercilii','Musculus corrugator supercilii',FE,'Small muscle deep to the eyebrow.','Medial end of the superciliary arch','Skin of the middle of the eyebrow','Temporal branches of the facial nerve (CN VII)','Draws the eyebrows medially and down (frowning)')
m('orbicularis_oculi_orbital','Orbicularis oculi – orbital part','Musculus orbicularis oculi, pars orbitalis',FE,'Outer ring of the sphincter around the eye.','Nasal part of frontal bone, frontal process of maxilla, medial palpebral ligament','Encircles the orbit and returns near its origin','Temporal and zygomatic branches of the facial nerve (CN VII)','Closes the eyelids tightly (squeezing)')
m('orbicularis_oculi_palpebral','Orbicularis oculi – palpebral part','Musculus orbicularis oculi, pars palpebralis',FE,'Thin inner part of the sphincter, within the eyelids.','Medial palpebral ligament','Lateral palpebral raphe','Temporal and zygomatic branches of the facial nerve (CN VII)','Closes the eyelids gently (blinking)')
m('nasalis','Nasalis','Musculus nasalis',FE,'Muscle of the external nose with transverse and alar parts.','Maxilla, above the incisor and canine teeth','Aponeurosis over the nasal dorsum and the alar cartilages','Buccal branches of the facial nerve (CN VII)','Compresses (transverse part) or flares (alar part) the nostrils')
m('depressor_septi_nasi','Depressor septi nasi','Musculus depressor septi nasi',FE,'Small muscle beneath the upper lip.','Maxilla above the central incisor','Mobile part of the nasal septum','Buccal branches of the facial nerve (CN VII)','Pulls the tip of the nose down')
m('levator_labii_superioris_alaeque_nasi','Levator labii superioris alaeque nasi','Musculus levator labii superioris alaeque nasi',FE,'Labelled "levator nasolabialis" in the source model.','Frontal process of the maxilla','Alar cartilage and skin of the upper lip','Zygomatic and buccal branches of the facial nerve (CN VII)','Elevates the upper lip and dilates the nostril')
m('levator_labii_superioris','Levator labii superioris','Musculus levator labii superioris',FE,'Flat muscle of the upper lip.','Infra-orbital margin of the maxilla, above the infra-orbital foramen','Skin and muscle of the upper lip','Zygomatic and buccal branches of the facial nerve (CN VII)','Elevates the upper lip')
m('levator_anguli_oris','Levator anguli oris','Musculus levator anguli oris',FE,'Lies deep to levator labii superioris.','Canine fossa of the maxilla, below the infra-orbital foramen','Angle of the mouth (modiolus)','Zygomatic and buccal branches of the facial nerve (CN VII)','Elevates the angle of the mouth')
m('zygomaticus_major','Zygomaticus major','Musculus zygomaticus major',FE,'The main "smiling" muscle.','Lateral surface of the zygomatic bone','Angle of the mouth (modiolus)','Zygomatic and buccal branches of the facial nerve (CN VII)','Draws the angle of the mouth upwards and laterally')
m('zygomaticus_minor','Zygomaticus minor','Musculus zygomaticus minor',FE,'Slender muscle medial to zygomaticus major.','Zygomatic bone','Upper lip','Zygomatic and buccal branches of the facial nerve (CN VII)','Elevates the upper lip')
m('risorius','Risorius','Musculus risorius',FE,'Thin, variable muscle of the cheek.','Fascia over the parotid gland and masseter','Angle of the mouth','Buccal branches of the facial nerve (CN VII)','Pulls the angle of the mouth laterally')
m('buccinator','Buccinator','Musculus buccinator',FE,'Muscle forming the wall of the cheek. The parotid duct pierces it.','Alveolar processes of maxilla and mandible opposite the molars; pterygomandibular raphe','Angle of the mouth, blending with orbicularis oris','Buccal branches of the facial nerve (CN VII)','Presses the cheek against the teeth, keeping food between them; used in blowing')
m('orbicularis_oris','Orbicularis oris','Musculus orbicularis oris',FE,'Sphincter muscle of the lips.','Maxilla and mandible near the midline, and fibres from other muscles at the modiolus','Skin and mucous membrane of the lips','Buccal and marginal mandibular branches of the facial nerve (CN VII)','Closes and protrudes the lips')
m('depressor_anguli_oris','Depressor anguli oris','Musculus depressor anguli oris',FE,'Triangular muscle below the corner of the mouth.','Oblique line of the mandible','Angle of the mouth','Marginal mandibular branch of the facial nerve (CN VII)','Pulls the angle of the mouth down (frowning)')
m('depressor_labii_inferioris','Depressor labii inferioris','Musculus depressor labii inferioris',FE,'Quadrilateral muscle of the lower lip.','Oblique line of the mandible, between the symphysis and mental foramen','Skin of the lower lip','Marginal mandibular branch of the facial nerve (CN VII)','Depresses the lower lip')
m('mentalis','Mentalis','Musculus mentalis',FE,'Small muscle of the chin.','Incisive fossa of the mandible','Skin of the chin','Marginal mandibular branch of the facial nerve (CN VII)','Raises and protrudes the lower lip; wrinkles the chin')
m('platysma','Platysma','Platysma',FE,'Broad, thin sheet in the superficial fascia of the neck.','Fascia over the upper pectoralis major and deltoid','Inferior border of the mandible, skin of the lower face and angle of the mouth','Cervical branch of the facial nerve (CN VII)','Tenses the skin of the neck; helps depress the mandible and corner of the mouth')
MA='Mastication'
m('temporalis','Temporalis','Musculus temporalis',MA,'Fan-shaped muscle filling the temporal fossa.','Floor of the temporal fossa and deep temporal fascia','Coronoid process and anterior border of the ramus of the mandible','Deep temporal nerves (mandibular nerve, V3)','Elevates the mandible; posterior fibres retract it')
m('masseter_superficial','Masseter – superficial part','Musculus masseter, pars superficialis',MA,'Larger, outer part of the masseter.','Zygomatic process of maxilla and anterior two-thirds of the lower border of the zygomatic arch','Angle and lower lateral surface of the ramus of the mandible','Masseteric nerve (mandibular nerve, V3)','Elevates the mandible (closes the jaw)')
m('masseter_deep','Masseter – deep part','Musculus masseter, pars profunda',MA,'Smaller, deeper part of the masseter.','Posterior third and deep surface of the zygomatic arch','Upper lateral surface of the ramus and coronoid process','Masseteric nerve (mandibular nerve, V3)','Elevates and helps retract the mandible')
m('medial_pterygoid','Medial pterygoid','Musculus pterygoideus medialis',MA,'Quadrangular muscle on the inner side of the ramus, mirroring the masseter.','Medial surface of the lateral pterygoid plate; maxillary tuberosity','Medial surface of the ramus near the angle of the mandible','Nerve to medial pterygoid (mandibular nerve, V3)','Elevates and protrudes the mandible; side-to-side grinding')
m('lateral_pterygoid_superior','Lateral pterygoid – superior head','Musculus pterygoideus lateralis, caput superius',MA,'Upper head of the lateral pterygoid.','Infratemporal surface of the greater wing of the sphenoid','Capsule and articular disc of the temporomandibular joint, and neck of the mandible','Nerve to lateral pterygoid (mandibular nerve, V3)','Stabilises the disc and condyle, especially during closing')
m('lateral_pterygoid_inferior','Lateral pterygoid – inferior head','Musculus pterygoideus lateralis, caput inferius',MA,'Lower head of the lateral pterygoid.','Lateral surface of the lateral pterygoid plate','Pterygoid fovea on the neck of the mandible','Nerve to lateral pterygoid (mandibular nerve, V3)','Protrudes the mandible and opens the jaw; side-to-side movement')
NK='Neck'
m('sternocleidomastoid','Sternocleidomastoid','Musculus sternocleidomastoideus',NK,'Key landmark dividing the neck into anterior and posterior triangles.','Manubrium of sternum (sternal head) and medial third of clavicle (clavicular head)','Mastoid process and lateral half of the superior nuchal line','Accessory nerve (CN XI)','One side: tilts the head to the same side and turns the face to the opposite side. Both sides: flex the neck')
m('digastric_anterior','Digastric – anterior belly','Musculus digastricus, venter anterior',NK,'Suprahyoid muscle beneath the chin.','Digastric fossa of the mandible','Intermediate tendon, attached to the hyoid bone','Nerve to mylohyoid (mandibular nerve, V3)','Depresses the mandible; elevates the hyoid')
m('digastric_posterior','Digastric – posterior belly','Musculus digastricus, venter posterior',NK,'Suprahyoid muscle running from the mastoid region to the hyoid.','Mastoid notch of the temporal bone','Intermediate tendon, attached to the hyoid bone','Facial nerve (CN VII)','Elevates and retracts the hyoid; assists jaw opening')
m('mylohyoid','Mylohyoid','Musculus mylohyoideus',NK,'Forms the muscular floor of the mouth.','Mylohyoid line of the mandible','Midline raphe and body of the hyoid bone','Nerve to mylohyoid (mandibular nerve, V3)','Elevates the hyoid and floor of the mouth (swallowing, speaking)')
m('stylohyoid','Stylohyoid','Musculus stylohyoideus',NK,'Slender suprahyoid muscle; its tendon splits around the digastric tendon.','Styloid process of the temporal bone','Body of the hyoid bone','Facial nerve (CN VII)','Elevates and retracts the hyoid')
EO='Extra-ocular'
m('levator_palpebrae_superioris','Levator palpebrae superioris','Musculus levator palpebrae superioris',EO,'Muscle of the upper eyelid.','Lesser wing of the sphenoid, above the optic canal','Skin and tarsal plate of the upper eyelid','Oculomotor nerve (CN III); its smooth-muscle part (superior tarsal) is sympathetic','Raises the upper eyelid')
m('superior_rectus','Superior rectus','Musculus rectus superior',EO,'One of the four rectus muscles of the eye.','Common tendinous ring','Superior sclera, in front of the equator','Oculomotor nerve (CN III)','Elevates the eye; also adducts and intorts it')
m('inferior_rectus','Inferior rectus','Musculus rectus inferior',EO,'One of the four rectus muscles of the eye.','Common tendinous ring','Inferior sclera, in front of the equator','Oculomotor nerve (CN III)','Depresses the eye; also adducts and extorts it')
m('medial_rectus','Medial rectus','Musculus rectus medialis',EO,'Largest of the rectus muscles.','Common tendinous ring','Medial sclera','Oculomotor nerve (CN III)','Adducts the eye')
m('lateral_rectus','Lateral rectus','Musculus rectus lateralis',EO,'One of the four rectus muscles of the eye.','Common tendinous ring','Lateral sclera','Abducens nerve (CN VI)','Abducts the eye')
m('superior_oblique','Superior oblique','Musculus obliquus superior',EO,'Its tendon runs through a pulley (the trochlea) before turning back to the eye.','Body of the sphenoid, above and medial to the optic canal','Posterosuperolateral sclera, via the trochlea','Trochlear nerve (CN IV)','Intorts, depresses and abducts the eye (depression is greatest when the eye is adducted)')
m('inferior_oblique','Inferior oblique','Musculus obliquus inferior',EO,'The only extra-ocular muscle arising from the front of the orbit.','Orbital surface of the maxilla, in the floor of the orbit','Posteroinferolateral sclera','Oculomotor nerve (CN III)','Extorts, elevates and abducts the eye (elevation is greatest when the eye is adducted)')
# ---------- nerves ----------
def n(s,name,latin,group,summary,fibres): add('nerve.'+s,name,latin,group,summary,fibres=fibres)
n('facial_nerve','Facial nerve (CN VII)','Nervus facialis','Cranial nerve','Leaves the skull at the stylomastoid foramen, passes through the parotid gland and fans out into temporal, zygomatic, buccal, marginal mandibular and cervical branches to the muscles of facial expression. Also carries taste from the anterior two-thirds of the tongue and secretomotor fibres to the lacrimal, submandibular and sublingual glands.','Motor, sensory (taste), parasympathetic')
n('chorda_tympani','Chorda tympani','Chorda tympani','Branch of CN VII','Crosses the middle ear next to the eardrum and joins the lingual nerve. Carries taste from the anterior two-thirds of the tongue and secretomotor fibres to the submandibular and sublingual glands.','Sensory (taste), parasympathetic')
n('trigeminal_nerve','Trigeminal nerve (CN V)','Nervus trigeminus','Cranial nerve','The main sensory nerve of the face, and motor to the muscles of mastication. Divides at the trigeminal ganglion into ophthalmic (V1), maxillary (V2) and mandibular (V3) nerves.','Sensory and motor')
n('trigeminal_sensory_root','Sensory root of trigeminal nerve','Radix sensoria nervi trigemini','Trigeminal nerve','Large root carrying sensation from the face to the pons.','Sensory')
n('trigeminal_motor_root','Motor root of trigeminal nerve','Radix motoria nervi trigemini','Trigeminal nerve','Small root that joins the mandibular nerve to supply the muscles of mastication.','Motor')
n('ophthalmic_nerve','Ophthalmic nerve (V1)','Nervus ophthalmicus','Trigeminal nerve','Enters the orbit through the superior orbital fissure as the frontal, lacrimal and nasociliary nerves. Supplies the forehead, upper eyelid, cornea and dorsum of the nose.','Sensory')
n('maxillary_nerve','Maxillary nerve (V2)','Nervus maxillaris','Trigeminal nerve','Leaves the skull through the foramen rotundum and continues as the infra-orbital nerve. Supplies the lower eyelid, cheek, upper lip, upper teeth, palate and nasal cavity.','Sensory')
n('mandibular_nerve_anterior','Mandibular nerve (V3) – anterior division','Nervus mandibularis','Trigeminal nerve','Mainly motor: masseteric, deep temporal and lateral pterygoid nerves. Its one sensory branch is the buccal nerve.','Mainly motor')
n('mandibular_nerve_posterior','Mandibular nerve (V3) – posterior division','Nervus mandibularis','Trigeminal nerve','Mainly sensory: auriculotemporal, lingual and inferior alveolar nerves. Its motor branch is the nerve to mylohyoid.','Mainly sensory')
n('buccal_nerve','Buccal nerve','Nervus buccalis','Mandibular nerve (V3)','Sensory to the skin and mucous membrane of the cheek. It does not supply the buccinator muscle, which is supplied by the facial nerve.','Sensory')
n('lingual_nerve','Lingual nerve','Nervus lingualis','Mandibular nerve (V3)','General sensation from the anterior two-thirds of the tongue, floor of the mouth and lingual gums. Carries chorda tympani fibres.','Sensory (+ chorda tympani fibres)')
n('inferior_alveolar_nerve','Inferior alveolar nerve','Nervus alveolaris inferior','Mandibular nerve (V3)','Enters the mandibular foramen and runs in the mandibular canal to supply the lower teeth. Anaesthetised in the dental "inferior alveolar nerve block".','Sensory (gives off the motor nerve to mylohyoid)')
n('mental_nerve','Mental nerve','Nervus mentalis','Mandibular nerve (V3)','Terminal branch of the inferior alveolar nerve; emerges from the mental foramen to supply the skin of the chin and the lower lip.','Sensory')
n('nerve_to_mylohyoid','Nerve to mylohyoid','Nervus mylohyoideus','Mandibular nerve (V3)','Branch of the inferior alveolar nerve supplying mylohyoid and the anterior belly of digastric.','Motor')
n('optic_nerve','Optic nerve (CN II)','Nervus opticus','Cranial nerve','Carries visual information from the retina through the optic canal to the optic chiasm.','Special sensory (vision)')
n('oculomotor_nerve','Oculomotor nerve (CN III)','Nervus oculomotorius','Cranial nerve','Supplies the superior, inferior and medial recti, inferior oblique and levator palpebrae superioris; its parasympathetic fibres constrict the pupil and focus the lens.','Motor, parasympathetic')
n('trochlear_nerve','Trochlear nerve (CN IV)','Nervus trochlearis','Cranial nerve','Supplies the superior oblique muscle. The only cranial nerve to leave the back of the brainstem.','Motor')
n('abducens_nerve','Abducens nerve (CN VI)','Nervus abducens','Cranial nerve','Supplies the lateral rectus muscle, which turns the eye outwards.','Motor')
n('hypoglossal_nerve','Hypoglossal nerve (CN XII)','Nervus hypoglossus','Cranial nerve','Motor to the intrinsic and most extrinsic muscles of the tongue (all except palatoglossus).','Motor')
# ---------- vessels ----------
def v(s,name,latin,group,summary): add('vessel.'+s,name,latin,group,summary)
AR='Artery'; VE='Vein'
v('external_carotid_artery','External carotid artery','Arteria carotis externa',AR,'Branch of the common carotid artery that supplies the face, scalp and neck. It ends in the parotid gland by dividing into the maxillary and superficial temporal arteries.')
v('internal_carotid_artery','Internal carotid artery','Arteria carotis interna',AR,'Gives no branches in the neck. Enters the skull through the carotid canal to supply the brain, and the orbit via the ophthalmic artery.')
v('facial_artery','Facial artery','Arteria facialis',AR,'Branch of the external carotid. Hooks over the mandible at the front of the masseter (where its pulse can be felt) and winds towards the medial corner of the eye.')
v('angular_artery','Angular artery','Arteria angularis',AR,'Terminal part of the facial artery beside the nose; anastomoses with branches of the ophthalmic artery.')
v('superior_labial_artery','Superior labial artery','Arteria labialis superior',AR,'Branch of the facial artery to the upper lip; joins its partner from the other side and sends branches to the nasal septum.')
v('inferior_labial_artery','Inferior labial artery','Arteria labialis inferior',AR,'Branch of the facial artery to the lower lip.')
v('submental_artery','Submental artery','Arteria submentalis',AR,'Branch of the facial artery running below the mandible to the chin and floor of the mouth.')
v('superficial_temporal_artery','Superficial temporal artery','Arteria temporalis superficialis',AR,'Terminal branch of the external carotid. Ascends in front of the ear, where its pulse can be felt, and supplies much of the scalp.')
v('superficial_temporal_artery_frontal_branch','Frontal branch of superficial temporal artery','Ramus frontalis arteriae temporalis superficialis',AR,'Supplies the scalp of the forehead; anastomoses with the supra-orbital and supratrochlear arteries.')
v('transverse_facial_artery','Transverse facial artery','Arteria transversa faciei',AR,'Branch of the superficial temporal artery running across the face below the zygomatic arch, with the parotid duct.')
v('maxillary_artery','Maxillary artery','Arteria maxillaris',AR,'Larger terminal branch of the external carotid. Passes behind the neck of the mandible to supply the jaws, teeth, muscles of mastication, nasal cavity, palate and dura (via the middle meningeal artery).')
v('inferior_alveolar_artery','Inferior alveolar artery','Arteria alveolaris inferior',AR,'Branch of the maxillary artery that runs with the inferior alveolar nerve in the mandibular canal to supply the lower teeth.')
v('infraorbital_artery','Infra-orbital artery','Arteria infraorbitalis',AR,'Continuation of the maxillary artery through the floor of the orbit, emerging at the infra-orbital foramen.')
v('occipital_artery','Occipital artery','Arteria occipitalis',AR,'Branch of the external carotid supplying the back of the scalp.')
v('ophthalmic_artery','Ophthalmic artery','Arteria ophthalmica',AR,'First branch of the internal carotid inside the skull; enters the orbit through the optic canal and supplies the eye (including the retina) and orbit.')
v('supraorbital_artery','Supra-orbital artery','Arteria supraorbitalis',AR,'Branch of the ophthalmic artery to the forehead and scalp.')
v('supratrochlear_artery','Supratrochlear artery','Arteria supratrochlearis',AR,'Terminal branch of the ophthalmic artery supplying the medial forehead.')
v('facial_vein','Facial vein','Vena facialis',VE,'Main vein of the face, running behind the facial artery. Connects with the cavernous sinus through the ophthalmic veins, which is why infections around the nose and upper lip ("danger triangle") are taken seriously.')
v('angular_vein','Angular vein','Vena angularis',VE,'Formed at the medial corner of the eye by the supratrochlear and supra-orbital veins; continues as the facial vein and communicates with the superior ophthalmic vein.')
v('superior_labial_vein','Superior labial vein','Vena labialis superior',VE,'Drains the upper lip into the facial vein.')
v('inferior_labial_veins','Inferior labial veins','Venae labiales inferiores',VE,'Drain the lower lip into the facial vein.')
v('submental_vein','Submental vein','Vena submentalis',VE,'Drains the chin and floor of the mouth into the facial vein.')
v('common_facial_vein','Common facial vein','Vena facialis communis',VE,'Short trunk formed by the facial vein and the anterior division of the retromandibular vein; drains into the internal jugular vein.')
v('retromandibular_vein','Retromandibular vein','Vena retromandibularis',VE,'Formed in the parotid gland by the superficial temporal and maxillary veins. Divides into an anterior division (to the common facial vein) and a posterior division (to the external jugular vein).')
v('superficial_temporal_veins','Superficial temporal veins','Venae temporales superficiales',VE,'Drain the side of the scalp and join the maxillary vein to form the retromandibular vein.')
v('internal_jugular_vein','Internal jugular vein','Vena jugularis interna',VE,'Begins at the jugular foramen and runs in the carotid sheath. Drains the brain, face and neck, then joins the subclavian vein to form the brachiocephalic vein.')
v('external_jugular_vein','External jugular vein','Vena jugularis externa',VE,'Formed near the angle of the mandible by the posterior auricular vein and the posterior division of the retromandibular vein; crosses sternocleidomastoid superficially to reach the subclavian vein.')
v('posterior_auricular_vein','Posterior auricular vein','Vena auricularis posterior',VE,'Drains the scalp behind the ear; helps form the external jugular vein.')
# ---------- organs ----------
o=lambda s,*a,**k: add('organ.'+s,*a,**k)
o('eyeball','Eyeball','Bulbus oculi','Eye','The globe of the eye. This model shows its outer coats: the white sclera, the transparent cornea and the iris.')
o('lacrimal_gland','Lacrimal gland','Glandula lacrimalis','Gland','Produces tears; sits in the upper outer part of the orbit. Its secretomotor supply comes from the facial nerve via the pterygopalatine ganglion.')
o('parotid_gland','Parotid gland','Glandula parotidea','Gland','The largest salivary gland, in front of and below the ear (model includes the accessory parotid). The facial nerve passes through it but does not supply it; its secretomotor fibres come from the glossopharyngeal nerve.')
o('parotid_duct','Parotid duct','Ductus parotideus','Gland','Also called Stensen\'s duct. Crosses the masseter, pierces buccinator and opens into the mouth opposite the upper second molar.')
o('submandibular_gland','Submandibular gland','Glandula submandibularis','Gland','Salivary gland under the body of the mandible. Its duct opens beside the frenulum of the tongue; secretomotor supply via the chorda tympani and submandibular ganglion.')
